public List<List<Integer>> permute(int[] nums) {
    List<List<Integer>> res = new ArrayList<>();
    if (nums == null) return res;
    int n = nums.length;
    boolean[] used = new boolean[n];
    List<Integer> current = new ArrayList<>(n);
    backtrack(nums, used, current, res);
    return res;
}

private void backtrack(int[] nums, boolean[] used, List<Integer> current, List<List<Integer>> res) {
    if (current.size() == nums.length) {
        res.add(new ArrayList<>(current));
        return;
    }
    for (int i = 0; i < nums.length; i++) {
        if (used[i]) continue;
        used[i] = true;
        current.add(nums[i]);
        backtrack(nums, used, current, res);
        current.remove(current.size() - 1);
        used[i] = false;
    }
}

public int findLargestSubstring(List<String> strings) {
    if (strings == null || strings.isEmpty()) {
        return 0;
    }
    String base = strings.get(0);
    int baseLen = base.length();
    // Map lengths to distinct substrings for the base string
    Map<Integer, Set<String>> substrByLen = new TreeMap<>(Collections.reverseOrder());
    for (int i = 0; i < baseLen; i++) {
        StringBuilder sb = new StringBuilder();
        for (int j = i; j < baseLen; j++) {
            sb.append(base.charAt(j));
            String sub = sb.toString();
            substrByLen.computeIfAbsent(sub.length(), k -> new HashSet<>()).add(sub);
        }
    }

    // Try substrings from longest to shortest
    for (Map.Entry<Integer, Set<String>> entry : substrByLen.entrySet()) {
        int len = entry.getKey();
        for (String sub : entry.getValue()) {
            String rev = new StringBuilder(sub).reverse().toString();
            boolean fits = true;
            for (String s : strings) {
                if (!(s.contains(sub) || s.contains(rev))) {
                    fits = false;
                    break;
                }
            }
            if (fits) {
                return len; // longest such substring found
            }
        }
    }
    return 0;
}

public static int countOilDeposits(char[][] grid) {
    if (grid == null || grid.length == 0 || grid[0].length == 0) {
        return 0;
    }
    int rows = grid.length;
    int cols = grid[0].length;
    boolean[][] visited = new boolean[rows][cols];
    int count = 0;
    int[] dx = {-1, -1, -1, 0, 0, 1, 1, 1};
    int[] dy = {-1, 0, 1, -1, 1, -1, 0, 1};

    for (int r = 0; r < rows; r++) {
        for (int c = 0; c < cols; c++) {
            if (grid[r][c] == '@' && !visited[r][c]) {
                count++;
                // BFS to mark all connected '@' cells
                java.util.ArrayDeque<int[]> stack = new java.util.ArrayDeque<>();
                stack.add(new int[]{r, c});
                visited[r][c] = true;
                while (!stack.isEmpty()) {
                    int[] cur = stack.removeLast();
                    int cr = cur[0], cc = cur[1];
                    for (int k = 0; k < 8; k++) {
                        int nr = cr + dx[k];
                        int nc = cc + dy[k];
                        if (nr >= 0 && nr < rows && nc >= 0 && nc < cols
                                && grid[nr][nc] == '@' && !visited[nr][nc]) {
                            visited[nr][nc] = true;
                            stack.add(new int[]{nr, nc});
                        }
                    }
                }
            }
        }
    }
    return count;
}

