public boolean canArrange(int[] arr, int k) {
    if (arr == null || arr.length % 2 != 0) {
        return false;
    }
    int[] freq = new int[k];
    for (int num : arr) {
        int rem = num % k;
        if (rem < 0) {
            rem += k;
        }
        freq[rem]++;
    }
    // Remainder 0 must pair with itself
    if (freq[0] % 2 != 0) {
        return false;
    }
    // Check the rest of the remainders
    for (int i = 1; i <= k / 2; i++) {
        int counterpart = k - i;
        if (i == counterpart) { // this happens when k is even and i == k/2
            if (freq[i] % 2 != 0) {
                return false;
            }
        } else {
            if (freq[i] != freq[counterpart]) {
                return false;
            }
        }
    }
    return true;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
