    List<Integer>[] graph = new ArrayList[n];
    for (int i = 0; i < n; ++i) graph[i] = new ArrayList<>();
    for (int[] e : edges) {
        int u = e[0], v = e[1];
        graph[u].add(v);
        graph[v].add(u);
    }

    // DFS to compute time needed for each subtree
    return dfs(0, -1, graph, hasApple);
}

private int dfs(int node, int parent, List<Integer>[] graph, boolean[] hasApple) {
    int time = 0;
    for (int child : graph[node]) {
        if (child == parent) continue;
        int sub = dfs(child, node, graph, hasApple);
        if (sub > 0 || hasApple[child]) {
            time += sub + 2; // go to child and back
        }
    }
    return time;
}

