public int minInsertions(String s) {
    int need = 0; // number of '(' needed to match
    int ans = 0;  // number of insertions required
    for (char c : s.toCharArray()) {
        if (c == '(') {
            need++;
        } else { // c == ')'
            need--;
            if (need < 0) {
                ans++;   // insert an '(' before this ')'
                need = 0; // after insertion, the unmatched ')' is balanced
            }
        }
    }
    // After the loop, any remaining '(' need to be closed by ')'
    ans += need;
    return ans;
}

