public int maxAbsoluteSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    int maxEnding = nums[0];
    int maxSoFar = nums[0];
    int minEnding = nums[0];
    int minSoFar = nums[0];
    for (int i = 1; i < nums.length; i++) {
        int val = nums[i];
        maxEnding = Math.max(val, maxEnding + val);
        maxSoFar = Math.max(maxSoFar, maxEnding);
        minEnding = Math.min(val, minEnding + val);
        minSoFar = Math.min(minSoFar, minEnding);
    }
    return Math.max(Math.abs(maxSoFar), Math.abs(minSoFar));
}

public int findMinFibonacciNumbers(int k) {
    // Generate Fibonacci numbers up to k
    java.util.ArrayList<Integer> fib = new java.util.ArrayList<>();
    fib.add(1);
    fib.add(1);
    while (true) {
        int size = fib.size();
        int next = fib.get(size - 1) + fib.get(size - 2);
        if (next > k) break;
        fib.add(next);
    }
    // Greedy subtraction from the largest Fibonacci number
    int count = 0;
    while (k > 0) {
        for (int i = fib.size() - 1; i >= 0; i--) {
            int f = fib.get(i);
            if (f <= k) {
                k -= f;
                count++;
                break;
            }
        }
    }
    return count;
}

public int kthFactor(int n, int k) {
    java.util.ArrayList<Integer> small = new java.util.ArrayList<>();
    java.util.ArrayList<Integer> large = new java.util.ArrayList<>();
    int sqrt = (int) Math.sqrt(n);
    for (int i = 1; i <= sqrt; i++) {
        if (n % i == 0) {
            small.add(i);
            int j = n / i;
            if (j != i) {
                large.add(j);
            }
        }
    }
    int total = small.size() + large.size();
    if (k > total) return -1;
    if (k <= small.size()) {
        return small.get(k - 1);
    } else {
        int idxInLarge = k - small.size() - 1;
        int revIdx = large.size() - 1 - idxInLarge;
        return large.get(revIdx);
    }
}

