public String getSmallestString(int n, int k) {
    // Start with a string of all 'a's
    char[] result = new char[n];
    for (int i = 0; i < n; i++) {
        result[i] = 'a';
    }

    int remaining = k - n; // how much we still need to add beyond all 'a's

    // Distribute the remaining value to the string from right to left
    for (int i = n - 1; i >= 0 && remaining > 0; i--) {
        int add = Math.min(25, remaining); // each character can increase at most 25 (from a to z)
        result[i] = (char) ('a' + add);
        remaining -= add;
    }

    return new String(result);
}

