public static int singleNumber(int[] nums) {
    int ones = 0, twos = 0;
    for (int num : nums) {
        twos |= ones & num;
        ones ^= num;
        int commonMask = ~(ones & twos);
        ones &= commonMask;
        twos &= commonMask;
    }
    return ones;
}

public static List<Integer> findSteppingNumbers(int low, int high) {
    if (low > high) return new ArrayList<>();
    TreeSet<Integer> result = new TreeSet<>();
    Queue<Long> queue = new LinkedList<>();
    for (int i = 0; i <= 9; i++) {
        if (i >= low && i <= high) result.add(i);
        queue.offer((long) i);
    }
    while (!queue.isEmpty()) {
        long num = queue.poll();
        if (num > high) continue;
        int lastDigit = (int) (num % 10);
        // Append digit - 1
        int nextDigit = lastDigit - 1;
        if (nextDigit >= 0) {
            long nextNum = num * 10 + nextDigit;
            if (nextNum <= high) {
                if (nextNum >= low) result.add((int) nextNum);
                queue.offer(nextNum);
            }
        }
        // Append digit + 1
        nextDigit = lastDigit + 1;
        if (nextDigit <= 9) {
            long nextNum = num * 10 + nextDigit;
            if (nextNum <= high) {
                if (nextNum >= low) result.add((int) nextNum);
                queue.offer(nextNum);
            }
        }
    }
    return new ArrayList<>(result);
}

public static int countDigitOne(int n) {
    if (n < 0) return 0;
    long count = 0;
    for (long factor = 1; factor <= n; factor *= 10) {
        long lower  = n % factor;
        long cur    = (n / factor) % 10;
        long higher = n / (factor * 10);
        if (cur == 0) {
            count += higher * factor;
        } else if (cur == 1) {
            count += higher * factor + lower + 1;
        } else {
            count += (higher + 1) * factor;
        }
    }
    return (int) count;
}

