                left[i][j] = (j > 0 ? left[i][j - 1] : 0) + 1;
                diag[i][j] = (i > 0 && j > 0 ? diag[i - 1][j - 1] : 0) + 1;
                anti[i][j] = (i > 0 && j < n - 1 ? anti[i - 1][j + 1] : 0) + 1;
                max = Math.max(max,
                        Math.max(up[i][j],
                                Math.max(left[i][j],
                                         Math.max(diag[i][j], anti[i][j]))));
            }
        }
    }
    return max;
}

public static String addThousandSeparator(int n) {
    boolean negative = n < 0;
    // Use long to safely handle Integer.MIN_VALUE
    long value = negative ? -(long) n : n;
    String num = Long.toString(value);
    int len = num.length();
    StringBuilder sb = new StringBuilder();
    int firstGroup = len % 3;
    if (firstGroup == 0) {
        firstGroup = 3;
    }
    sb.append(num.substring(0, firstGroup));
    for (int i = firstGroup; i < len; i += 3) {
        sb.append('.');
        sb.append(num.substring(i, i + 3));
    }
    if (negative) {
        sb.insert(0, '-');
    }
    return sb.toString();
}

public static int squarePermutations(int[] A) {
    int n = A.length;
    if (n == 0) return 0;
    // Compute set of perfect squares up to maximum possible sum
    int maxVal = 0;
    for (int v : A) if (v > maxVal) maxVal = v;
    int maxSum = maxVal * 2;
    boolean[] isSquare = new boolean[maxSum + 1];
    for (int r = 1; r * r <= maxSum; r++) {
        isSquare[r * r] = true;
    }

    // adjacency matrix where can[i][j] is true if A[i] + A[j] is a perfect square
    boolean[][] can = new boolean[n][n];
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (i != j && isSquare[A[i] + A[j]]) {
                can[i][j] = true;
            }
        }
    }

    int fullMask = (1 << n) - 1;
    long[][] dp = new long[1 << n][n];

    // Initialize DP for single-element permutations
    for (int i = 0; i < n; i++) {
        dp[1 << i][i] = 1;
    }

    // DP over subsets
    for (int mask = 0; mask <= fullMask; mask++) {
        for (int last = 0; last < n; last++) {
            long curWays = dp[mask][last];
            if (curWays == 0) continue;
            for (int next = 0; next < n; next++) {
                if ((mask & (1 << next)) == 0 && can[last][next]) {
                    int newMask = mask | (1 << next);
                    dp[newMask][next] += curWays;
                }
            }
        }
    }

    // Sum all permutations that use all elements
    long totalPerms = 0;
    for (int last = 0; last < n; last++) {
        totalPerms += dp[fullMask][last];
    }

    // Count frequencies of each value to account for duplicates
    java.util.Map<Integer, Integer> freq = new java.util.HashMap<>();
    for (int v : A) {
        freq.put(v, freq.getOrDefault(v, 0) + 1);
    }

    long divisor = 1;
    for (int count : freq.values()) {
        long fact = 1;
        for (int i = 2; i <= count; i++) {
            fact *= i;
        }
        divisor *= fact;
    }

    long result = totalPerms / divisor;
    return (int) result;
}

public static int largestRectangleArea(int[] heights) {
    if (heights == null || heights.length == 0) return 0;
    int n = heights.length;
    int maxArea = 0;
    java.util.Deque<Integer> stack = new java.util.ArrayDeque<>();
    for (int i = 0; i <= n; i++) {
        int curHeight = (i == n) ? 0 : heights[i];
        while (!stack.isEmpty() && curHeight < heights[stack.peek()]) {
            int height = heights[stack.pop()];
            int width = stack.isEmpty() ? i : i - stack.peek() - 1;
            int area = height * width;
            if (area > maxArea) {
                maxArea = area;
            }
        }
        stack.push(i);
    }
    return maxArea;
}

public static int[] diagonalOrder(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) {
        return new int[0];
    }
    int m = mat.length;
    int n = mat[0].length;
    int[] result = new int[m * n];
    int index = 0;
    for (int k = 0; k < m + n - 1; k++) {
        if ((k & 1) == 0) { // even diagonal, traverse up-right
            int r = Math.min(k, m - 1);
            int c = k - r;
            while (r >= 0 && c < n) {
                result[index++] = mat[r][c];
                r--;
                c++;
            }
        } else { // odd diagonal, traverse down-left
            int c = Math.min(k, n - 1);
            int r = k - c;
            while (c >= 0 && r < m) {
                result[index++] = mat[r][c];
                r++;
                c--;
            }
        }
    }
    return result;
}

public static int findSmallestInteger(int n) {
    // Convert the integer to a char array representing its digits
    char[] digits = Integer.toString(n).toCharArray();
    int len = digits.length;

    // Step 1: Find the first index from the end where digits[i] < digits[i+1]
    int pivot = len - 2;
    while (pivot >= 0 && digits[pivot] >= digits[pivot + 1]) {
        pivot--;
    }

    // If no pivot found, the digits are in the highest possible order
    if (pivot < 0) {
        return -1;
    }

    // Step 2: Find the smallest digit on the right side of the pivot that is greater than digits[pivot]
    int successor = len - 1;
    while (digits[successor] <= digits[pivot]) {
        successor--;
    }

    // Step 3: Swap the pivot with the successor
    char temp = digits[pivot];
    digits[pivot] = digits[successor];
    digits[successor] = temp;

    // Step 4: Reverse the suffix starting at pivot + 1
    int left = pivot + 1;
    int right = len - 1;
    while (left < right) {
        temp = digits[left];
        digits[left] = digits[right];
        digits[right] = temp;
        left++;
        right--;
    }

    // Convert back to integer and check for overflow
    try {
        return Integer.parseInt(new String(digits));
    } catch (NumberFormatException e) {
        // Overflow: the next permutation would exceed Integer.MAX_VALUE
        return -1;
    }
}

public static List<String> centerSymmetricNumbers(int n) {
    List<String> result = new ArrayList<>();
    if (n == 0) return result;
    char[] arr = new char[n];
    build(0, n - 1, arr, result);
    return result;
}

private static void build(int left, int right, char[] arr, List<String> result) {
    if (left > right) {
        result.add(new String(arr));
        return;
    }
    if (left == right) {
        for (char c : new char[]{'0', '1', '8'}) {
            arr[left] = c;
            result.add(new String(arr));
        }
        return;
    }
    char[][] pairs = {{'0', '0'}, {'1', '1'}, {'6', '9'}, {'8', '8'}, {'9', '6'}};
    for (char[] p : pairs) {
        if (left == 0 && p[0] == '0') continue; // skip leading zero
        arr[left] = p[0];
        arr[right] = p[1];
        build(left + 1, right - 1, arr, result);
    }
}

public static boolean isBoomerang(int[][] points) {
    if (points == null || points.length != 3) {
        return false;
    }

    // Ensure all points are distinct
    for (int i = 0; i < 3; i++) {
        for (int j = i + 1; j < 3; j++) {
            if (points[i][0] == points[j][0] && points[i][1] == points[j][1]) {
                return false;
            }
        }
    }

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Compute the cross product of vectors (p2-p1) and (p3-p1)
    int cross = (x2 - x1) * (y3 - y1) - (x3 - x1) * (y2 - y1);
    return cross != 0;
}

public static int findNthUglyNumber(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] ugly = new int[n];
    ugly[0] = 1;
    int i2 = 0, i3 = 0, i5 = 0;
    int next2 = 2, next3 = 3, next5 = 5;
    for (int i = 1; i < n; i++) {
        int nextUgly = Math.min(next2, Math.min(next3, next5));
        ugly[i] = nextUgly;
        if (nextUgly == next2) {
            i2++;
            next2 = ugly[i2] * 2;
        }
        if (nextUgly == next3) {
            i3++;
            next3 = ugly[i3] * 3;
        }
        if (nextUgly == next5) {
            i5++;
            next5 = ugly[i5] * 5;
        }
    }
    return ugly[n - 1];
}

public static int calculateEnergy(String s) {
    if (s == null || s.isEmpty()) {
        return 0;
    }
    int max = 1;
    int current = 1;
    for (int i = 1; i < s.length(); i++) {
        if (s.charAt(i) == s.charAt(i - 1)) {
            current++;
        } else {
            if (current > max) {
                max = current;
            }
            current = 1;
        }
    }
    if (current > max) {
        max = current;
    }
    return max;
}

public static List<Integer> lexicalOrder(int n) {
    List<Integer> result = new ArrayList<>(n);
    long current = 1;
    for (int count = 0; count < n; count++) {
        result.add((int) current);
        if (current * 10 <= n) {
            current *= 10;
        } else {
            while (current % 10 == 9 || current + 1 > n) {
                current /= 10;
            }
            current++;
        }
    }
    return result;
}

public static int calculateUniqueSum(int[] nums) {
    if (nums == null || nums.length == 0) {
        return 0;
    }
    java.util.Map<Integer, Integer> counts = new java.util.HashMap<>();
    for (int num : nums) {
        counts.put(num, counts.getOrDefault(num, 0) + 1);
    }
    int sum = 0;
    for (java.util.Map.Entry<Integer, Integer> entry : counts.entrySet()) {
        if (entry.getValue() == 1) {
            sum += entry.getKey();
        }
    }
    return sum;
}

public static int minPerfectSquareSum(int n) {
    if (n <= 0) {
        return 0;
    }
    int[] dp = new int[n + 1];
    dp[0] = 0;
    for (int i = 1; i <= n; i++) {
        dp[i] = i; // maximum number of 1^2 needed (worst case)
        int j = 1;
        while (j * j <= i) {
            int square = j * j;
            int candidate = dp[i - square] + 1;
            if (candidate < dp[i]) {
                dp[i] = candidate;
            }
            j++;
        }
    }
    return dp[n];
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) return s;
    String[] words = s.split("\\s+");
    StringBuilder result = new StringBuilder();
    for (int i = 0; i < words.length; i++) {
        result.append(new StringBuilder(words[i]).reverse());
        if (i < words.length - 1) {
            result.append(" ");
        }
    }
    return result.toString();
}
